/**
 * `buildFacts` – engine-confirmed facts for explanations (PRD P0-11, D-19). The SAN of every move is generated by
 * `@/lib/chess` (chess.js) from **engine PVs only**; motifs come from the rule-based detectors and are kept only when
 * the engine line confirms them (e.g. a hanging piece is reported only if the refutation captures it).
 *
 * Meaning of the fields per `kind` (contract `ExplanationFacts` in `@/core`):
 * - `mistake` (game review) / `coach_warning` (before a move, P0-08): `mover` played `playedMove` in `fenBefore`;
 *   `bestMove`/`bestLine` = engine PV in `fenBefore`; `refutation` = engine PV after the played move (opponent's
 *   best reply first); `materialSwing` = mover's material change along played move + refutation; `mateIn` < 0 when
 *   the mover gets mated after the move, > 0 when the best line mates (for a mistake: the played move gives it up).
 * - `praise`: like `mistake`, for a strong move (motifs = what the move achieves).
 * - `threat` (coach, `findThreats`): `mover` = side to move in `fenBefore` (the threatened side); `refutation` = the
 *   opponent's threat line, computed from the null-move position (`nullMoveFen(fenBefore)`), threat move first;
 *   `materialSwing` = mover's material change along that line; `mateIn` < 0 for a mate threat; `bestMove`/`bestLine`
 *   (optional) = the engine's best defence in `fenBefore`.
 * - `puzzle`: `bestLine` = solution line from `fenBefore`; `themes` = puzzle themes.
 */
import type { Color, Fen, San, Uci } from '@/core/chess';
import type { Score } from '@/core/engine';
import type { ExplanationFacts, MotifInstance } from '@/core/explain';
import { ChessGame, nullMoveFen, parseFen, uciLineToSan, uciToSan } from '@/lib/chess';
import {
  detectBackRankWeakness,
  detectHangingPieces,
  detectMaterialLoss,
  detectMotifs,
  detectTrappedPieces,
  materialSwing,
} from './motifs';
import { otherColor } from './see';

/** Maximum plies of a line in the facts (mating lines are kept up to the mate, at most `MAX_MATE_LINE`). */
export const MAX_LINE_PLIES = 8;
export const MAX_MATE_LINE = 16;

/** Input of `buildFacts`; lines are engine PVs in UCI. */
export interface BuildFactsInput {
  /** Position before the explained move (for `threat`: the position of the threatened side, who is to move). */
  fenBefore: Fen;
  /** Played / attempted move (mistake, coach_warning, praise). */
  playedMove?: Uci;
  /** Engine PV in `fenBefore`, best move first (puzzle: the solution). */
  bestLine?: readonly Uci[];
  /** Score of `bestLine` (White POV, D-08). */
  bestScore?: Score;
  /** Engine PV after the played move (opponent's reply first); for `threat` the threat line from the null-move position. */
  refutation?: readonly Uci[];
  /** Score of the position after the played move (White POV); for `threat` the score of the threat line. */
  refutationScore?: Score;
  /** Expected-points loss 0–1. */
  expectedPointsLoss?: number;
  /** Puzzle themes (Lichess keys). */
  themes?: string[];
}

function turnOf(fen: Fen): Color {
  return parseFen(fen)?.turn ?? 'w';
}

/** Mate distance from `pov`'s view (positive = `pov` mates), `undefined` for a centipawn score or mate 0. */
function mateFor(score: Score | undefined, pov: Color): number | undefined {
  if (!score || score.type !== 'mate' || score.value === 0) return undefined;
  return pov === 'w' ? score.value : -score.value;
}

/** Truncates a line: `MAX_LINE_PLIES`, or up to the mate (≤ `MAX_MATE_LINE`) for mating lines. */
function cut(line: readonly Uci[], mateIn: number | undefined): Uci[] {
  const limit = mateIn !== undefined ? Math.min(MAX_MATE_LINE, Math.max(MAX_LINE_PLIES, Math.abs(mateIn) * 2)) : MAX_LINE_PLIES;
  return line.slice(0, limit);
}

/** Legal prefix of a line as UCI (SAN conversion stops at the first illegal move). */
function legalPrefix(fen: Fen, line: readonly Uci[]): { uci: Uci[]; san: San[] } {
  const san = uciLineToSan(fen, line);
  return { uci: line.slice(0, san.length), san };
}

function positionAfter(fen: Fen, line: readonly Uci[]): Fen | null {
  try {
    const game = ChessGame.fromFen(fen);
    for (const m of line) if (!game.move(m)) return null;
    return game.fen();
  } catch {
    return null;
  }
}

function dedupe(motifs: MotifInstance[]): MotifInstance[] {
  const seen = new Set<string>();
  return motifs.filter((m) => {
    const key = `${m.id}:${m.squares.join(',')}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/** Squares on which the side `capturer` captures along a line from `fen`. */
function captureSquares(fen: Fen, line: readonly Uci[], capturer: Color): Set<string> {
  const out = new Set<string>();
  try {
    const game = ChessGame.fromFen(fen);
    for (const m of line) {
      const rec = game.move(m);
      if (!rec) break;
      if (rec.captured && rec.color === capturer) out.add(rec.to);
    }
  } catch {
    // illegal start position: no captures
  }
  return out;
}

/** Motifs explaining why `mover`'s position collapses along `line` (opponent to move first) from `fen`. */
function victimMotifs(fen: Fen, line: readonly Uci[], mover: Color, mateIn: number | undefined): MotifInstance[] {
  const opp = otherColor(mover);
  const motifs: MotifInstance[] = [];
  const captured = captureSquares(fen, line, opp);
  motifs.push(...detectHangingPieces(fen, mover).filter((m) => captured.has(m.squares[0]!)));
  const reply = line[0];
  if (reply) {
    // Hanging pieces are reported above (with all attackers); keep the other motifs the reply creates.
    motifs.push(...detectMotifs(fen, reply).filter((m) => m.id !== 'hanging_piece'));
    const afterReply = positionAfter(fen, [reply]);
    if (afterReply) motifs.push(...detectTrappedPieces(afterReply, mover).filter((m) => captured.has(m.squares[0]!)));
  }
  if (mateIn !== undefined && mateIn < 0 && line.length > 0) {
    const sans = uciLineToSan(fen, line);
    const last = line[sans.length - 1];
    if (sans.at(-1)?.endsWith('#') && last) {
      motifs.push({ id: 'mate', squares: [last.slice(0, 2), last.slice(2, 4)] as MotifInstance['squares'], pieces: [] });
    } else if (reply) {
      motifs.push({ id: 'mate_threat', squares: [reply.slice(0, 2), reply.slice(2, 4)] as MotifInstance['squares'], pieces: [] });
    }
    const backRank = detectBackRankWeakness(fen, mover);
    if (backRank) motifs.push(backRank);
  }
  const loss = detectMaterialLoss(fen, line, mover);
  if (loss) motifs.push(loss);
  return motifs;
}

/**
 * Builds `ExplanationFacts` from engine lines (see the file header for the meaning per `kind`). Lines are cut to the
 * legal prefix and to `MAX_LINE_PLIES` (mating lines up to the mate); SAN is generated by chess.js.
 */
export function buildFacts(kind: ExplanationFacts['kind'], input: BuildFactsInput): ExplanationFacts {
  const { fenBefore } = input;
  const mover = turnOf(fenBefore);
  const opp = otherColor(mover);
  const facts: ExplanationFacts = { kind, mover, fenBefore, bestLine: [], refutation: [], motifs: [] };
  if (input.expectedPointsLoss !== undefined) facts.expectedPointsLoss = input.expectedPointsLoss;
  if (input.themes) facts.themes = [...input.themes];

  const bestMate = mateFor(input.bestScore, mover);
  const best = legalPrefix(fenBefore, cut(input.bestLine ?? [], bestMate));
  facts.bestLine = best.san;
  if (best.uci[0] && best.san[0]) facts.bestMove = { uci: best.uci[0], san: best.san[0] };

  if (kind === 'threat') {
    const nullFen = nullMoveFen(fenBefore);
    const threatMate = mateFor(input.refutationScore, mover);
    if (nullFen) {
      const threat = legalPrefix(nullFen, cut(input.refutation ?? [], threatMate));
      facts.refutation = threat.san;
      facts.materialSwing = materialSwing(nullFen, threat.uci, mover);
      if (threatMate !== undefined) facts.mateIn = threatMate;
      facts.motifs = dedupe(victimMotifs(nullFen, threat.uci, mover, threatMate));
    }
    return facts;
  }

  if (kind === 'puzzle') {
    facts.materialSwing = materialSwing(fenBefore, best.uci, mover);
    if (bestMate !== undefined) facts.mateIn = bestMate;
    const motifs: MotifInstance[] = [];
    best.uci.forEach((m, i) => {
      if (i % 2 === 1) return;
      const pos = positionAfter(fenBefore, best.uci.slice(0, i));
      if (pos) motifs.push(...detectMotifs(pos, m));
    });
    facts.motifs = dedupe(motifs);
    return facts;
  }

  const played = input.playedMove;
  const playedSan = played ? uciToSan(fenBefore, played) : null;
  if (!played || !playedSan) return facts;
  facts.playedMove = { uci: played, san: playedSan };
  const fenAfter = positionAfter(fenBefore, [played]);
  if (!fenAfter) return facts;
  const afterMate = mateFor(input.refutationScore, mover);
  const refutation = legalPrefix(fenAfter, cut(input.refutation ?? [], afterMate));
  facts.refutation = refutation.san;
  facts.materialSwing = materialSwing(fenBefore, [played, ...refutation.uci], mover);
  // < 0: the mover gets mated after the move; > 0: the best line mates (a mistake gives that up, praise achieves it).
  if (afterMate !== undefined && afterMate < 0) facts.mateIn = afterMate;
  else if (bestMate !== undefined && bestMate > 0) facts.mateIn = bestMate;

  if (kind === 'praise') {
    const motifs = detectMotifs(fenBefore, played);
    if (afterMate !== undefined && afterMate > 0 && !motifs.some((m) => m.id === 'mate')) {
      motifs.push({ id: 'mate_threat', squares: [played.slice(0, 2), played.slice(2, 4)] as MotifInstance['squares'], pieces: [] });
    }
    facts.motifs = dedupe(motifs);
    return facts;
  }

  // mistake / coach_warning
  const motifs = victimMotifs(fenAfter, refutation.uci, mover, afterMate);
  const playedIsBest = best.uci[0] === played;
  if (!playedIsBest && best.uci.length > 0) {
    const bestGain = materialSwing(fenBefore, best.uci, mover);
    const playedGain = facts.materialSwing ?? 0;
    const bestMates = bestMate !== undefined && bestMate > 0 && !(afterMate !== undefined && afterMate > 0);
    // A missed win: the best line mates or wins ≥ 2 pawns itself, and the played move gets ≥ 2 pawns less.
    if (bestMates || (bestGain >= 2 && bestGain - playedGain >= 2)) {
      const from = best.uci[0]!.slice(0, 2);
      const to = best.uci[0]!.slice(2, 4);
      motifs.push({
        id: 'missed_win',
        squares: [from, to] as MotifInstance['squares'],
        pieces: [],
        ...(bestGain - playedGain >= 2 ? { gain: bestGain - playedGain } : {}),
      });
    }
  }
  if (refutation.uci.some((m) => m.length === 5)) {
    const game = ChessGame.fromFen(fenAfter);
    for (const m of refutation.uci) {
      const rec = game.move(m);
      if (!rec) break;
      if (rec.promotion && rec.color === opp) {
        motifs.push({ id: 'promotion', squares: [rec.from, rec.to], pieces: [{ square: rec.to, piece: rec.promotion, color: opp }] });
        break;
      }
    }
  }
  facts.motifs = dedupe(motifs);
  return facts;
}
